WITH matched_keys AS (SELECT firmware FROM device_readings EXCEPT DISTINCT SELECT firmware FROM device_readings WHERE pressure BETWEEN 1005 AND 1015), verified AS (SELECT s.* FROM device_readings s JOIN matched_keys k ON s.firmware = k.firmware) SELECT CASE WHEN status_bits >= 9 THEN 'HIGH' ELSE 'LOW' END AS status_bits_tier, BIT_OR(status_bits) AS status_bits_bit_or, ROUND(SUM(humidity) / NULLIF(COUNT(CASE WHEN device_code = 'DV-01' THEN 1 END), 0), 2) AS humidity_per_dv_01, SUM(CASE WHEN device_code = 'DV-04' THEN pressure ELSE 0 END) AS dv_04_pressure FROM verified GROUP BY 1 ORDER BY status_bits_bit_or NULLS FIRST
